#!/usr/bin/env python3
"""Generate tests/null_cases.rs: one case per exported function, called with all
arguments zeroed (NULL pointers / 0 integers).  Each case is executed in its own
subprocess so that a genuine C-side dereference of NULL is itself a comparable
observable (exit signal) instead of killing the test run."""
import re
import os

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SRC = os.path.join(ROOT, 'translation/tests/common/api_gen.rs')

lines = open(SRC).read().split('\n')

pub, priv_ = [], []
cur = pub
for ln in lines:
    if ln.startswith('api! {'):
        cur = pub
        continue
    if ln.startswith('api_priv! {'):
        cur = priv_
        continue
    m = re.match(r'\s*fn (\w+)\(([^)]*)\)(?:\s*->\s*(.+))?;', ln)
    if m:
        cur.append((m.group(1), m.group(2), (m.group(3) or '').strip()))


def zero(t):
    t = t.strip()
    if t.startswith('*mut') or t.startswith('*const'):
        return 'core::ptr::null_mut()' if t.startswith('*mut') else 'core::ptr::null()'
    if t in ('f64', 'f32'):
        return '0.0'
    return '0'


def fmt_ret(rt, expr):
    if rt == '':
        return f'{{ {expr}; "void".to_string() }}'
    if rt.startswith('*'):
        return f'{{ let v = {expr}; format!("ptr_null={{}}", v.is_null()) }}'
    return f'format!("{{:?}}", {expr})'


cases = []
for group, items in (('api', pub), ('pv', priv_)):
    for name, args, rt in items:
        alist = [a for a in args.split(',') if a.strip()]
        zs = ', '.join(zero(a) for a in alist)
        expr = f'(l.{group}.{name})({zs})'
        cases.append((name, fmt_ret(rt, expr)))

out = []
out.append('// GENERATED by tools/gen_null_cases.rs -- do not edit by hand.')
out.append('// One case per exported symbol, invoked with every argument zeroed.')
out.append('pub const NCASES: usize = %d;' % len(cases))
out.append('')
out.append('pub const NAMES: [&str; NCASES] = [')
for name, _ in cases:
    out.append('    "%s",' % name)
out.append('];')
out.append('')
out.append('/// Invoke case `i` with all-zero arguments and return a printable result.')
out.append('pub fn run_case(l: &Lib, i: usize) -> String {')
out.append('    unsafe {')
out.append('        match i {')
for idx, (name, body) in enumerate(cases):
    out.append('            %d => %s,' % (idx, body))
out.append('            _ => "no such case".to_string(),')
out.append('        }')
out.append('    }')
out.append('}')

open(os.path.join(ROOT, 'translation/tests/common/null_cases.rs'), 'w').write('\n'.join(out) + '\n')
print('cases:', len(cases))
